      "type": "code",
      "param": {
        "variables": [
          ["raw", ["text", "2"]]
        ],
        "outputs": [
          ["queries", "array[string]"]
        ],
        "code": "def main(raw: str):\n\timport json, re\n\t# Try direct JSON parse\n\tdata = None\n\ttry:\n\t\tdata = json.loads(raw)\n\texcept Exception:\n\t\t# Extract first JSON object\n\t\tm = re.search(r\"\\{[\\s\\S]*\\}\", raw)\n\t\tif m:\n\t\t\tdata = json.loads(m.group(0))\n\tif not isinstance(data, dict) or \"queries\" not in data:\n\t\traise ValueError(\"LLM output must be JSON with key 'queries'.\")\n\tqueries = data.get(\"queries\")\n\tif not isinstance(queries, list):\n\t\traise ValueError(\"'queries' must be a list.\")\n\t# Normalize, drop empties\n\tclean = []\n\tfor q in queries:\n\t\tif q is None:\n\t\t\tcontinue\n\t\tq = str(q).strip()\n\t\tif q:\n\t\t\tclean.append(q)\n\t# Ensure exactly 3 queries\n\tif len(clean) < 3:\n\t\t# pad by duplicating last if needed (rare)\n\t\twhile len(clean) < 3:\n\t\t\tclean.append(clean[-1] if clean else \"\")\n\telif len(clean) > 3:\n\t\tclean = clean[:3]\n\treturn {\"queries\": clean}\n"
      }
    },
