        "code": "def main(url: str):\n\timport re\n\tfrom urllib.parse import urlparse\n\tu = (url or '').strip()\n\tif not u:\n\t\traise ValueError('Empty url')\n\t# Accept formats like:\n\t# https://github.com/OWNER/REPO\n\t# https://github.com/OWNER/REPO/\n\t# https://github.com/OWNER/REPO/tree/branch/path\n\t# git@github.com:OWNER/REPO.git\n\towner = repo = None\n\tif u.startswith('git@'):\n\t\tm = re.search(r'github\\.com:([^/]+)/([^/]+?)(?:\\.git)?$', u)\n\t\tif m:\n\t\t\towner, repo = m.group(1), m.group(2)\n\telse:\n\t\tp = urlparse(u)\n\t\tpath = (p.path or '').strip('/')\n\t\tparts = [x for x in path.split('/') if x]\n\t\tif len(parts) >= 2 and (p.netloc.endswith('github.com') or p.netloc == ''):\n\t\t\towner, repo = parts[0], parts[1]\n\tif not owner or not repo:\n\t\traise ValueError('Invalid GitHub repo url. Expected https://github.com/<owner>/<repo>')\n\trepo = repo[:-4] if repo.endswith('.git') else repo\n\t# Use Git Trees API via default branch reference (HEAD) and recursive=1\n\tapi_url = f\"https://api.github.com/repos/{owner}/{repo}/git/trees/HEAD?recursive=1\"\n\treturn {\n\t\t\"owner\": owner,\n\t\t\"repo\": repo,\n\t\t\"api_url\": api_url\n\t}"
