        "code": "def main(body: str):\n\timport json\n\tdata = json.loads(body or '{}')\n\t# Expected: { \"tree\": [ {\"path\":..., \"type\": \"blob\"|\"tree\", ...}, ... ], ... }\n\ttree = data.get('tree') or []\n\t# Normalize into a compact structure\n\tout = []\n\tfor item in tree:\n\t\tpath = item.get('path')\n\t\ttype_ = item.get('type')  # blob=file, tree=dir\n\t\tif not path or not type_:\n\t\t\tcontinue\n\t\tout.append({\n\t\t\t\"path\": path,\n\t\t\t\"kind\": \"dir\" if type_ == 'tree' else \"file\" if type_ == 'blob' else type_,\n\t\t\t\"size\": item.get('size'),\n\t\t\t\"sha\": item.get('sha')\n\t\t})\n\t# Sort: dirs first, then files; then path\n\tout.sort(key=lambda x: (0 if x.get('kind') == 'dir' else 1, x.get('path') or ''))\n\treturn {\"file_structure\": out}\n\t"
