        "code": "def main(body: str, repo: str):\n\timport json\n\tdata = json.loads(body or '{}')\n\titems = data.get('tree') or []\n\t# Build a nested dict tree where dict = directory, None = file\n\troot = {}\n\tfor it in items:\n\t\tpath = it.get('path')\n\t\ttype_ = it.get('type')\n\t\tif not path or type_ not in ('tree', 'blob'):\n\t\t\tcontinue\n\t\tparts = [p for p in path.split('/') if p]\n\t\tnode = root\n\t\tfor i, part in enumerate(parts):\n\t\t\tis_last = (i == len(parts) - 1)\n\t\t\tif is_last:\n\t\t\t\tif type_ == 'tree':\n\t\t\t\t\tnode = node.setdefault(part, {})\n\t\t\t\telse:\n\t\t\t\t\tnode.setdefault(part, None)\n\t\t\telse:\n\t\t\t\tnode = node.setdefault(part, {})\n\n\tdef render(node: dict, level: int):\n\t\tlines = []\n\t\t# directories first, then files; alphabetical\n\t\tdirs = sorted([k for k, v in node.items() if isinstance(v, dict)])\n\t\tfiles = sorted([k for k, v in node.items() if v is None])\n\t\tindent = '  ' * level\n\t\tfor d in dirs:\n\t\t\tlines.append(f\"{indent}{d}/\")\n\t\t\tlines.extend(render(node[d], level + 1))\n\t\tfor f in files:\n\t\t\tlines.append(f\"{indent}{f}\")\n\t\treturn lines\n\n\theader = (repo or 'repo').strip() or 'repo'\n\tlines = [f\"{header}/\"] + render(root, 1)\n\treturn {\"file_structure\": \"\\n\".join(lines)}\n\t"
