        "code": "def main(html: str):\n\timport re\n\tif html is None:\n\t\thtml = \"\"\n\t# remove scripts/styles\n\thtml = re.sub(r\"(?is)<script[^>]*>.*?</script>\", \" \", html)\n\thtml = re.sub(r\"(?is)<style[^>]*>.*?</style>\", \" \", html)\n\t# try to capture main content blocks first\n\tcandidates = []\n\tfor pat in [\n\t\tr\"(?is)<main[^>]*>(.*?)</main>\",\n\t\tr\"(?is)<article[^>]*>(.*?)</article>\",\n\t\tr\"(?is)<div[^>]+id=['\\\"]content['\\\"][^>]*>(.*?)</div>\",\n\t\tr\"(?is)<div[^>]+class=['\\\"][^'\\\"]*(?:content|post|article|entry|main)[^'\\\"]*['\\\"][^>]*>(.*?)</div>\",\n\t]:\n\t\tm = re.search(pat, html)\n\t\tif m:\n\t\t\tcandidates.append(m.group(1))\n\t# fallback to body\n\tif not candidates:\n\t\tm = re.search(r\"(?is)<body[^>]*>(.*?)</body>\", html)\n\t\tcandidates.append(m.group(1) if m else html)\n\tbest = max(candidates, key=lambda s: len(s) if s else 0) if candidates else \"\"\n\t# strip tags\n\ttext = re.sub(r\"(?is)<[^>]+>\", \" \", best)\n\t# decode a few common entities\n\ttext = text.replace(\"&nbsp;\", \" \").replace(\"&amp;\", \"&\").replace(\"&lt;\", \"<\").replace(\"&gt;\", \">\").replace(\"&quot;\", \"\\\"\").replace(\"&#39;\", \"'\")\n\t# normalize whitespace\n\ttext = re.sub(r\"[ \\t\\r\\f\\v]+\", \" \", text)\n\ttext = re.sub(r\"\\n{3,}\", \"\\n\\n\", text)\n\ttext = text.strip()\n\treturn {\"content\": text}\n"
      }
